options(stringsAsFactors=FALSE)
suppressPackageStartupMessages(library(ggplot2));suppressPackageStartupMessages(library(patchwork))
root<-normalizePath(commandArgs(TRUE)[1],winslash='/');data<-file.path(root,'results');out<-file.path(root,'figures');dir.create(out,recursive=TRUE,showWarnings=FALSE)
rd<-function(n)read.csv(file.path(data,n))
theme_set(theme_classic(base_size=10)+theme(plot.title=element_text(face='bold',size=10),legend.position='bottom',legend.title=element_blank()))
cols<-c('Age only'='#555555','Joint'='#0072B2')
jointlabs<-c('Age only'='Age only','Joint'='Joint age-ethnicity')
savefig<-function(p,name,w,h){tiff(file.path(out,name),width=w,height=h,units='in',res=600,compression='lzw',type='cairo');print(p);dev.off()}
rr<-subset(rd('annual_rate_gamma_intervals.csv'),definition=='D1_all_malignant');rr$group<-factor(rr$group,levels=c('20-49','50+'),labels=c('Ages 20-49','Ages 50+'))
p1<-ggplot(rr,aes(year,rate,color=method,fill=method))+geom_ribbon(aes(ymin=lower,ymax=upper),alpha=.12,color=NA,show.legend=FALSE)+geom_line(linewidth=.6)+facet_wrap(~group,scales='free_y')+scale_color_manual(values=cols,labels=jointlabs)+scale_fill_manual(values=cols)+scale_y_continuous(limits=c(0,NA))+labs(title='A  All malignant gallbladder tumors (D1)',x='Year',y='Incidence per 100,000')
shares<-rd('population_shares.csv');rn<-c('Hispanic (All Races)'='Hispanic','Non-Hispanic White'='Non-Hispanic White','Non-Hispanic Black'='Non-Hispanic Black','Non-Hispanic Asian or Pacific Islander'='Non-Hispanic Asian/Pacific Islander','Non-Hispanic American Indian/Alaska Native'='Non-Hispanic AI/AN')
shares$race<-factor(unname(rn[shares$race]),levels=unname(rn));shares$group<-factor(shares$group,levels=c('20-49','50+'),labels=c('Ages 20-49','Ages 50+'))
rc<-c('#D55E00','#0072B2','#009E73','#CC79A7','#E69F00');names(rc)<-unname(rn)
p2<-ggplot(shares,aes(year,share*100,color=race))+geom_line(linewidth=.6)+facet_wrap(~group)+scale_color_manual(values=rc)+scale_y_continuous(limits=c(0,100))+labs(title='B  Observed population composition',x='Year',y='Population share (%)')+guides(color=guide_legend(nrow=2))
savefig(p1/p2,'Figure_1_Incidence_and_population.tiff',10,7)
lab<-c('D1_all_malignant'='D1 all malignant','SEER_variants'='SEER variants','D4_strict_8140_3'='D4 adenocarcinoma NOS')
z<-subset(rd('original_wls_intervals.csv'),estimand=='younger');z$population<-factor(unname(lab[z$definition]),levels=rev(unname(lab)));z$method<-ifelse(z$reference=='2000','Joint','Age only')
p3<-ggplot(z,aes(estimate,population,color=method))+geom_vline(xintercept=0,lty=2,color='grey65')+geom_errorbar(aes(xmin=lower,xmax=upper),orientation='y',width=.15,position=position_dodge(width=.35))+geom_point(position=position_dodge(width=.35),size=2)+scale_color_manual(values=cols,labels=jointlabs)+labs(title='A  Younger-group APCs',x='Annual percentage change (%)',y=NULL)
z<-subset(rd('paired_apc_differences.csv'),group=='20-49'&window=='2000-2023'&method=='Paired smooth Poisson');z$population<-factor(unname(lab[z$definition]),levels=rev(unname(lab)))
p4<-ggplot(z,aes(difference_pp,population))+geom_vline(xintercept=0,lty=2,color='grey65')+geom_errorbar(aes(xmin=lower,xmax=upper),orientation='y',width=.15,color='#0072B2')+geom_point(color='#0072B2',size=2)+labs(title='B  Paired differences and 95% bootstrap CIs',x='Joint age-ethnicity minus age-only APC\n(percentage points/year)',y=NULL)
savefig(p3+p4,'Figure_2_Paired_trend_comparison.tiff',10,4.5)
z<-subset(rd('pooled_ethnic_rates_shares.csv'),group=='20-49');z$race<-factor(unname(rn[z$race]),levels=rev(unname(rn)))
p5<-ggplot(z,aes(rate,race,color=period,shape=period))+geom_errorbar(aes(xmin=lower,xmax=upper),orientation='y',width=.15,position=position_dodge(width=.4))+geom_point(position=position_dodge(width=.4),size=2)+scale_color_manual(values=c('#555555','#0072B2'))+scale_x_continuous(limits=c(0,NA))+labs(title='A  D1 ethnic rates, ages 20-49',x='Age-standardized incidence per 100,000',y=NULL)
z<-subset(rd('ethnic_decomposition.csv'),definition=='D1_all_malignant'&group=='20-49'&comparison=='pooled_latest'&component=='Composition'&method=='Plug-in Poisson');z$race<-ifelse(z$race=='Total','Total composition',unname(rn[z$race]));z$race<-factor(z$race,levels=c(rev(unname(rn)),'Total composition'))
p6<-ggplot(z,aes(estimate,race))+geom_vline(xintercept=0,lty=2,color='grey65')+geom_errorbar(aes(xmin=lower,xmax=upper),orientation='y',width=.15,color='#0072B2')+geom_point(color='#0072B2',size=2)+labs(title='B  2000-2004 versus 2019-2023',x='Composition component per 100,000',y=NULL)
savefig(p5+p6,'Figure_3_Ethnic_rates_and_components.tiff',11,4.7)
fit<-subset(rd('generator_fitted_annual_rates.csv'),group=='20-49')
fit$definition<-factor(unname(lab[fit$definition]),levels=unname(lab))
fdat<-rbind(data.frame(fit[c('definition','year')],method='Age only',Observed=fit$observed_age_only,Fitted=fit$fitted_age_only),data.frame(fit[c('definition','year')],method='Joint age-ethnicity',Observed=fit$observed_joint,Fitted=fit$fitted_joint))
long<-rbind(data.frame(fdat[c('definition','year','method')],series='Observed',rate=fdat$Observed),data.frame(fdat[c('definition','year','method')],series='Fitted generator',rate=fdat$Fitted))
p7<-ggplot(long,aes(year,rate,color=series,linetype=series))+geom_line(linewidth=.6)+facet_grid(definition~method)+scale_color_manual(values=c('Observed'='#555555','Fitted generator'='#0072B2'))+scale_linetype_manual(values=c('Observed'='solid','Fitted generator'='dashed'))+scale_y_continuous(limits=c(0,NA))+labs(x='Year',y='Incidence per 100,000',title='Observed and fitted annual rates, ages 20-49')
ggsave(file.path(data,'Figure_S1_Generator_fit.png'),p7,width=7,height=6,dpi=300)
ss<-subset(rd('nonlinear_time_curves.csv'),definition=='D1_all_malignant'&group=='20-49');ss$method<-factor(ss$method,levels=c('Age only','Joint'),labels=c('Age only','Joint age-ethnicity'))
oo<-subset(rd('annual_rates.csv'),definition=='D1_all_malignant'&group=='20-49');oo$method<-factor(oo$method,levels=c('Age only','Joint'),labels=c('Age only','Joint age-ethnicity'))
p8<-ggplot(ss,aes(year,rate))+geom_ribbon(aes(ymin=lower,ymax=upper),fill='#0072B2',alpha=.15)+geom_line(color='#0072B2',linewidth=.7)+geom_point(data=oo,aes(year,rate),size=1.2,color='#555555')+facet_wrap(~method)+scale_y_continuous(limits=c(0,NA))+labs(x='Year',y='Incidence per 100,000',title='Calendar-time spline sensitivity, D1 ages 20-49')
ggsave(file.path(data,'Figure_S2_Calendar_spline.png'),p8,width=7,height=3.5,dpi=300)
